def make_detail(df, field, output_name, country_mode=False):
    import pandas as pd
    rows = []
    for _, r in df.iterrows():
        raw = r[field]
        tokens = [] if pd.isna(raw) else [x.strip() for x in str(raw).split(",") if x.strip()]
        n = len(tokens)
        for i, token in enumerate(tokens, 1):
            d = {"show_id": r["show_id"], "title": r["title"], output_name: token, "token_order": i}
            if country_mode:
                d["country_count"] = n
                d["fractional_credit"] = 1.0 / n if n else None
            rows.append(d)
    cols = ["show_id", "title", output_name, "token_order"] + (["country_count", "fractional_credit"] if country_mode else [])
    return pd.DataFrame(rows, columns=cols)

def build_country(df):
    return make_detail(df, "country", "country", True)

