def compare_full_claim(full_top, old_top, full_base, old_base):
    import pandas as pd
    qualified=full_base.loc[full_base['title_credit']>=25,['market','title_credit']].merge(old_base[['market','title_credit']],on='market',how='left',suffixes=('_full','_conservative'))
    qualified['credit_gain']=qualified['title_credit_full']-qualified['title_credit_conservative']
    gains=qualified.sort_values(['credit_gain','market'],ascending=[False,True]).head(5)
    entrants=sorted(set(full_top['market'])-set(old_top['market']))
    leavers=sorted(set(old_top['market'])-set(full_top['market']))
    rows=[]
    for m in entrants: rows.append({'comparison':'entrant','market':m,'credit_gain':None})
    for m in leavers: rows.append({'comparison':'leaver','market':m,'credit_gain':None})
    for _,r in gains.iterrows(): rows.append({'comparison':'top_credit_gain','market':r['market'],'credit_gain':float(r['credit_gain'])})
    return pd.DataFrame(rows)

