def compare_entropy_top5(fractional, full):
    import pandas as pd
    f=fractional.head(5); g=full.head(5)
    fs=list(f["market"]); gs=list(g["market"])
    rows=[]
    for m in fs:
        if m in gs:
            rows.append({"list_type":"retained","market":m,"fractional_rank":int(f.loc[f.market==m,"rank"].iloc[0]),"full_claim_rank":int(g.loc[g.market==m,"rank"].iloc[0])})
    for m in gs:
        if m not in fs:
            rows.append({"list_type":"enters_full_claim_top5","market":m,"fractional_rank":None,"full_claim_rank":int(g.loc[g.market==m,"rank"].iloc[0])})
    for m in fs:
        if m not in gs:
            rows.append({"list_type":"leaves_full_claim_top5","market":m,"fractional_rank":int(f.loc[f.market==m,"rank"].iloc[0]),"full_claim_rank":None})
    rows.append({"list_type":"summary","market":"top5_overlap","fractional_rank":len(set(fs)&set(gs)),"full_claim_rank":None})
    return pd.DataFrame(rows)

